import {EmployeeNumerom} from './employeeNumerom';
export type EmployeeInput = {name:string;surname:string;birth_date:string|null;department:string;role:string;skills:string[];experience:string;interests:string[];hours_per_week:number|null};
export type Employee = EmployeeInput & {id:string};
export type GroupInput = {name:string;task:string;required_skills:string[];target_hours:number|null;member_ids:string[]};
export type Group = GroupInput & {id:string};
export type Workspace = {id:string;company_name:string;revision:number;employees:Employee[];groups:Group[];created_at:string;updated_at:string};
export type BusinessEnvelope = {package:{id:'business-250';title:string;max_employees:250;mode:'pilot';price:0};workspace:Workspace|null};
export type ImportIssue = {row:number;field:string;message:string};
export type ImportPreview = {employees:EmployeeInput[];issues:ImportIssue[];warnings:ImportIssue[];row_count:number;valid:boolean};
export type GroupReport = {name:string;task:string;member_count:number;coverage:{skill:string;employee_ids:string[]}[];missing_skills:string[];available_hours:number|null;target_hours:number|null;missing_hours_data:string[];next_steps:string[];members:Employee[]};
export type EmployeeAnalysis = {employee:Employee;numerom:EmployeeNumerom;workspace_revision:number;status:'needs_evidence'|'ready_for_discussion';skills:string[];experience:string;interests:string[];hours_per_week:number|null;task_matches:{id:string;name:string;task:string;matched_skills:string[];unconfirmed_skills:string[];is_member:boolean}[];missing_data:string[];next_steps:string[];basis:string};
export function businessEnvelope(value:unknown):BusinessEnvelope;
export function businessWorkspace(value:unknown):Workspace;
export function businessPreview(value:unknown):ImportPreview;
export function businessReport(value:unknown):GroupReport;
export function parseSkillList(value:string):string[];
export function employeeInput(value:{name:string;surname:string;birth_date?:string|null;department?:string;role?:string;skills?:string|string[];experience?:string;interests?:string|string[];hours_per_week?:string|number|null}):EmployeeInput;
export function businessReportHtml(value:unknown,companyName:string):string;
export function businessEmployeeAnalysis(value:unknown,employeeId:string):EmployeeAnalysis;
export function businessEmployeeAnalysisHtml(value:unknown,employeeId:string):string;
export function businessWorkspaceHtml(value:unknown):string;
export function validateBusinessFile(filename:unknown,size:unknown):string;
export function businessTemplate(filename:unknown,content:unknown):{filename:string;content:string};
